import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { notFound } from 'next/navigation';
import ReactMarkdown from 'react-markdown';
import Link from 'next/link';
import AiSubNav from '@/app/ai/_components/AiSubNav';

interface PageProps {
  params: Promise<{ slug: string }>;
}

export default async function LabDetailPage({ params }: PageProps) {
  const resolvedParams = await params;
  const { slug } = resolvedParams;
  
  if (!slug) return notFound();

  const decodedSlug = decodeURIComponent(slug);
  const contentPath = path.join(process.cwd(), 'content', 'lab');

  if (!fs.existsSync(contentPath)) return notFound();

  const fileNames = fs.readdirSync(contentPath);
  const targetFile = fileNames.find((fileName) => {
    const fileNameWithoutExt = fileName.replace(/\.(mdx|md)$/i, '');
    return fileNameWithoutExt.toLowerCase() === decodedSlug.toLowerCase();
  });

  if (!targetFile) return notFound();

  const fullPath = path.join(contentPath, targetFile);
  const fileContents = fs.readFileSync(fullPath, 'utf8');
  const { data, content } = matter(fileContents);

  return (
    <main className="fixed inset-0 bg-black overflow-hidden">
      {/* ✅ WORK 페이지와 동일한 배경 설정 */}
      <div
        className="absolute inset-0 bg-center bg-no-repeat bg-contain"
        style={{ backgroundImage: "url(/images/contents_bg.jpg)" }}
      />

      <div className="relative z-10 h-full max-w-6xl mx-auto px-6 py-10 text-white flex flex-col">
        {/* 헤더 부분: WORK 페이지 디자인 복사 */}
        <div className="flex items-start justify-between shrink-0">
          <div>
            <div className="text-xs tracking-[0.22em] text-white/70">CATEGORY</div>
            <h1 className="text-2xl mt-1 uppercase">AI CONTENTS</h1>
            {/* 서브 네비게이션: 간격 및 스타일 유지 */}
            <AiSubNav />
          </div>

          <Link
            href="/ai/lab"
            className="cursor-pointer px-4 py-2 rounded-full border border-white/20 bg-black/30 backdrop-blur-md hover:bg-white hover:text-black transition"
          >
            BACK
          </Link>
        </div>

        {/* ✅ 본문 영역: WORK 페이지의 스크롤 영역과 동일하게 처리 */}
        <div className="mt-8 flex-1 overflow-auto pr-2 custom-scrollbar">
          <article className="max-w-4xl">
            <header className="mb-10 border-b border-white/10 pb-6">
              <p className="text-white/50 font-mono text-sm mb-2">{data.date}</p>
              <h2 className="text-3xl font-bold text-white">{data.title}</h2>
              {data.summary && <p className="text-white/70 mt-4 text-lg">{data.summary}</p>}
            </header>
            
            {/* 마크다운 본문 디자인 가공 */}
            <div className="prose prose-invert max-w-none 
              prose-p:text-white/80 prose-p:leading-8 prose-p:mb-6
              prose-headings:text-white prose-headings:font-bold prose-headings:mt-12 prose-headings:mb-6
              prose-strong:text-yellow-400 prose-ul:list-disc prose-li:text-white/70">
              <ReactMarkdown>{content}</ReactMarkdown>
            </div>
          </article>
          <div className="h-20" /> {/* 하단 여백 유지 */}
        </div>
      </div>
    </main>
  );
}